mapper.select:
select a.* , b.catename from foods a , cate b where a.cateid = b.cateid

	and a.foodsname = #{foodsname}


	and a.image = #{image}


	and a.cateid = #{cateid}


	and a.price = #{price}


	and a.recommend = #{recommend}


	and a.special = #{special}


	and a.addtime = #{addtime}


	and a.hits = #{hits}


	and a.sellnum = #{sellnum}


	and a.contents = #{contents}
